export const artifactViewerStyles = ":root{color-scheme:light dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;background:#f5f5f4;color:#1c1917}*{box-sizing:border-box}body{margin:0}button,a{font:inherit}.artifact-shell{min-height:100vh;background:#f5f5f4;color:#1c1917}.artifact-shell.dark{background:#0c0a09;color:#e7e5e4}.artifact-shell>header{display:flex;align-items:flex-start;justify-content:space-between;gap:2rem;padding:2.25rem max(1.25rem,calc((100vw - 980px)/2));border-bottom:1px solid #d6d3d1;background:color-mix(in srgb,currentColor 3%,transparent)}.dark>header{border-color:#292524}.eyebrow{color:#16a34a;font-size:.72rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase}h1{margin:.45rem 0 .35rem;font-size:clamp(1.6rem,4vw,2.5rem);line-height:1.1}header p{max-width:56rem;margin:0;color:#78716c;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.78rem;overflow-wrap:anywhere}nav{display:flex;gap:.6rem;flex:none}nav a,nav button{border:1px solid #a8a29e;border-radius:.55rem;padding:.55rem .8rem;background:transparent;color:inherit;cursor:pointer;text-decoration:none}main{width:min(980px,calc(100% - 2.5rem));margin:0 auto;padding:3rem 0 5rem}.markdown{font-size:1rem;line-height:1.72}.markdown h1,.markdown h2,.markdown h3,.markdown h4{margin:2em 0 .65em;line-height:1.2}.markdown h1{font-size:2rem}.markdown h2{font-size:1.45rem;padding-bottom:.35rem;border-bottom:1px solid #d6d3d1}.dark .markdown h2{border-color:#292524}.markdown a{color:#15803d}.markdown table{width:100%;border-collapse:collapse;display:block;overflow-x:auto}.markdown th,.markdown td{padding:.65rem .8rem;border:1px solid #d6d3d1;text-align:left;vertical-align:top}.dark .markdown th,.dark .markdown td{border-color:#44403c}.markdown blockquote{margin-left:0;padding-left:1rem;border-left:3px solid #22c55e;color:#57534e}.dark .markdown blockquote{color:#a8a29e}.markdown code{border-radius:.3rem;padding:.1rem .3rem;background:#e7e5e4;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em}.dark .markdown code{background:#292524}.code-shell{position:relative;margin:1.25rem 0}.code-shell pre{margin:0;padding:1rem;overflow:auto;border:1px solid #d6d3d1;border-radius:.6rem;background:#fafaf9}.dark .code-shell pre{border-color:#44403c;background:#1c1917}.code-shell pre code{padding:0;background:transparent}.code-title{padding:.45rem .8rem;border:1px solid #d6d3d1;border-bottom:0;border-radius:.6rem .6rem 0 0;color:#78716c;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.75rem}.code-title+pre{border-radius:0 0 .6rem .6rem}.copy-button{position:absolute;top:.55rem;right:.55rem;width:2rem;height:2rem;padding:.4rem;border:1px solid #a8a29e;border-radius:.4rem;background:#fafaf9;color:inherit;cursor:pointer}.dark .copy-button{background:#292524}.copy-button svg{width:100%;height:100%}@media(max-width:720px){.artifact-shell>header{flex-direction:column}nav{width:100%}nav a,nav button{flex:1;text-align:center}}\n";
